 function multiplier(){return 1+DATA.gear.filter(i=>i.mult).reduce((s,i)=>s+count(i.id)*i.mult,0)}
 function missionDuration(){return Math.max(3,10-DATA.vehicles.reduce((s,i)=>s+count(i.id)*(i.bonus?i.bonus*14:0),0))}
 function missionReward(){return Math.max(5,Math.round((5+passive()*.45)*(1+Math.log10(1+state.totalEarned/1000)*.15)))}
 function clickPower(){return 1+DATA.gear.filter(i=>i.click).reduce((s,i)=>s+count(i.id)*i.click,0)}
+ function hitsPerAttack(){return Math.min(10,1+count('comboGloves'))}
 function repLevel(){return Math.max(1,Math.floor(Math.sqrt(state.totalEarned/250))+1)}
 function teamCount(){return DATA.heroes.reduce((s,i)=>s+count(i.id),0)}
 function save(){state.last=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){}}
